
#pragma once

#include <stddef.h>
#include <inttypes.h>

#include "base.c"
#include "params2.h"


typedef uint64_t ImplicState[16];

// the full implication state generated by the rule
static ImplicState full_implic_state;

// these return the implic state mask for where the cell
// at position pos in the 10-bit state is unknown, off, or on, respectively
static ImplicState IMPLICSTATE_CELL_MASKS[10][3];

// IMPLICSTATE_PAIR_SAME_MASKS[pos1][pos2] returns the implic state mask for
// where the cells at position pos1 and pos2 have the same value
// and IMPLICSTATE_PAIR_DIFFERENT_MASKS is the same thing but the cell values must be different
static ImplicState IMPLICSTATE_PAIR_SAME_MASKS[10][10];
static ImplicState IMPLICSTATE_PAIR_DIFFERENT_MASKS[10][10];


static inline int implicstate_get_bit(const ImplicState state, int bit) {
    return (state[bit >> 6] >> (bit & 63)) & 1;
}

static inline void implicstate_set_bit(ImplicState state, int bit, int value) {
    if (value == 0) {
        state[bit >> 6] &= ~((uint64_t)1 << (bit & 63));
    } else {
        state[bit >> 6] |= ((uint64_t)1 << (bit & 63));
    }
}

static inline void implicstate_and(ImplicState x, const ImplicState y) {
    for (int i = 0; i < 16; i++) {
        x[i] &= y[i];
    }
}

[[maybe_unused]] static void print_implicstate(const ImplicState state) {
    printf("Implication state:\n");
    int k = 0;
    for (int i = 0; i < 16; i++) {
        print_line_padding();
        for (int j = 0; j < 64; j++) {
            real_printf("%i", implicstate_get_bit(state, k));
            k++;
        }
        real_printf("\n");
    }
}

static void init_implicstate_masks(void) {
    for (int i = 0; i < 1024; i++) {
        if (state.rule_func[i] == IFV_UNSAT) {
            implicstate_set_bit(full_implic_state, i, 0);
        } else {
            implicstate_set_bit(full_implic_state, i, 1);
        }
    }
    debug(4, print_implicstate(full_implic_state));
    for (int pos = 0; pos < 10; pos++) {
        for (int i = 0; i < 16; i++) {
            IMPLICSTATE_CELL_MASKS[pos][0][i] = UINT64_MAX;
        }
        for (int i = 0; i < 1024; i++) {
            implicstate_set_bit(IMPLICSTATE_CELL_MASKS[pos][convert_01_to_12((i >> pos) & 1)], i, 1);
        }
    }
    for (int pos1 = 0; pos1 < 10; pos1++) {
        for (int pos2 = 0; pos2 < 10; pos2++) {
            for (int i = 0; i < 1024; i++) {
                if ((i >> pos1) == (i >> pos2)) {
                    implicstate_set_bit(IMPLICSTATE_PAIR_SAME_MASKS[pos1][pos2], i, 1);
                } else {
                    implicstate_set_bit(IMPLICSTATE_PAIR_DIFFERENT_MASKS[pos1][pos2], i, 1);
                }
            }
        }
    }
}

// implication bytecode format:
// 6 bit instructions, packed where the first instructions to execute are lower in significance
// instruction format: 0bvvpppp
// where v is the value to set it to, and p is the position index
// this only uses up instructions starting with 01 or 10
// so instruction 000000 is do nothing and stop (there are no further instructions)
// and instruction 000001 means there is a contradiction

// array of 59049 uint64_t's containing implication bytecode
uint64_t* implication_table;

static uint64_t get_implications_for_tr(uint32_t tr) {
    CellValue next = (tr / 1) % 3;
    CellValue se = (tr / 3) % 3;
    CellValue e = (tr / 9) % 3;
    CellValue ne = (tr / 27) % 3;
    CellValue s = (tr / 81) % 3;
    CellValue c = (tr / 243) % 3;
    CellValue n = (tr / 729) % 3;
    CellValue sw = (tr / 2187) % 3;
    CellValue w = (tr / 6561) % 3;
    CellValue nw = (tr / 19683) % 3;
    CellValue cells[10] = {next, se, e, ne, s, c, n, sw, w, nw};
    ImplicState state;
    memcpy(state, full_implic_state, sizeof(ImplicState));
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[0][next]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[1][se]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[2][e]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[3][ne]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[4][s]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[5][c]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[6][n]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[7][sw]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[8][w]);
    implicstate_and(state, IMPLICSTATE_CELL_MASKS[9][nw]);
    uint64_t out = 0;
    for (int pos = 0; pos < 10; pos++) {
        uint64_t* mask_0 = IMPLICSTATE_CELL_MASKS[pos][OFF];
        uint64_t* mask_1 = IMPLICSTATE_CELL_MASKS[pos][ON];
        uint64_t any_can_be_0 = 0;
        uint64_t any_can_be_1 = 0;
        for (int i = 0; i < 16; i++) {
            any_can_be_0 |= (state[i] & mask_0[i]);
            any_can_be_1 |= (state[i] & mask_1[i]);
        }
        bool can_be_0 = any_can_be_0 != 0;
        bool can_be_1 = any_can_be_1 != 0;
        if (!can_be_0 && !can_be_1) {
            // contradiction;
            return 1;
        } else if (!can_be_0 && can_be_1) {
            if (cells[pos] == UNKNOWN) {
                out <<= 6;
                out |= (ON << 4) | pos;
            }
        } else if (can_be_0 && !can_be_1) {
            if (cells[pos] == UNKNOWN) {
                out <<= 6;
                out |= (OFF << 4) | pos;
            }
        } else {
            // do nothing
        }
    }
    return out;
}

static void init_implications(void) {
    init_implicstate_masks();
    implication_table = safe_malloc(59049 * sizeof(uint64_t));
    for (uint32_t tr = 0; tr < 59049; tr++) {
        implication_table[tr] = get_implications_for_tr(tr);
    }
}

static void destroy_implications(void) {
    safe_free(implication_table);
}


static bool set_cell(Cell* cell, CellValue value) {
    debug(4, printf("Setting cell: variable = %zu, value = %i, prev_value = %i\n", cell->var_number, value, cell->value));
    cell->value = value;
    if (value == OFF) {
        for (size_t i = 0; i < cell->use_count; i++) {
            Clause** data = cell->uses[i];
            for (int i = 0; i < MAX_IMPLIC_FUNC_LENGTH; i++) {
                if (data[i] != NULL) {
                    data[i]->implication_pointer += POWERS_OF_3[i];
                }
            }
        }
    } else {
        for (size_t i = 0; i < cell->use_count; i++) {
            Clause** data = cell->uses[i];
            for (int i = 0; i < MAX_IMPLIC_FUNC_LENGTH; i++) {
                if (data[i] != NULL) {
                    data[i]->implication_pointer += POWERS_OF_3[i] * 2;
                }
            }
        }
    }
    return true;
}

static void unset_cell(Cell* cell) {
    debug(4, printf("Unsetting cell: variable = %zu: prev_value = %i\n", cell->var_number, cell->value));
    if (cell->value == OFF) {
        for (size_t i = 0; i < cell->use_count; i++) {
            Clause** data = cell->uses[i];
            for (int i = 0; i < MAX_IMPLIC_FUNC_LENGTH; i++) {
                if (data[i] != NULL) {
                    data[i]->implication_pointer -= POWERS_OF_3[i];
                }
            }
        }
    } else {
        for (size_t i = 0; i < cell->use_count; i++) {
            Clause** data = cell->uses[i];
            for (int i = 0; i < MAX_IMPLIC_FUNC_LENGTH; i++) {
                if (data[i] != NULL) {
                    data[i]->implication_pointer -= POWERS_OF_3[i] * 2;
                }
            }
        }
    }
    cell->value = UNKNOWN;
}

static void init_clause_implication_tr(Clause* clause) {
    clause->implication_pointer = implication_table;
    for (int i = 0; i < MAX_IMPLIC_FUNC_LENGTH; i++) {
        if (clause->cells[i] != NULL) {
            clause->implication_pointer += clause->cells[i]->value * POWERS_OF_3[i];
        }
    }
    debug(4, printf("Transition for clause %zu: %ti\n", clause->number, clause->implication_pointer - implication_table));
}


static bool set_cell_and_propagate(Cell* cell, CellValue value, bool is_explicit);

// returns false if contradiction, true if no contradiction
static inline bool check_clause_implications(Clause* clause) {
    if (clause == NULL) {
        return true;
    }
    uint64_t code = *clause->implication_pointer;
    debug(4, printf("Implication for clause %zu: transition = %ti, code = %"PRIu64"\n", clause->number, clause->implication_pointer - implication_table, code));
    if (code == 1) {
        debug(3, printf("Contradiction in check_implications\n"));
        debug(4, print_grid(stdout));
        return false;
    }
    while (code != 0) {
        int instruction = ((int)code) & 63;
        Cell* cell = clause->cells[instruction & 15];
        CellValue value = instruction >> 4;
        if (!set_cell_and_propagate(cell, value, false)) {
            return false;
        }
        code >>= 6;
    }
    return true;
}

static inline bool check_cell_implications(Cell* cell) {
    debug(4, printf("Checking implications for variable %zu\n", cell->var_number));
    inc_debug_depth();
    for (size_t i = 0; i < cell->use_count; i++) {
        Clause** data = cell->uses[i];
        for (int i = 0; i < MAX_IMPLIC_FUNC_LENGTH; i++) {
            if (!check_clause_implications(data[i])) {
                dec_debug_depth();
                return false;
            }
        }
    }
    dec_debug_depth();
    return true;
}

// set a cell in the search state, propagating checks
// returns false if contradiction, true if no contradiction
static bool set_cell_and_propagate(Cell* cell, CellValue value, bool is_explicit) {
    debug(3, printf("Setting cell and propagating: var_number = %zu, value = %i\n", cell->var_number, value));
    if (cell->value != UNKNOWN) {
        // unexpected_error("Setting known cell");
        return cell->value == value;
    }
    if (!set_cell_and_push(cell, value, is_explicit)) {
        return false;
    }
    return check_cell_implications(cell);
}
